from pathlib import Path

TARGET = Path('backend/core/scheduler/jobs/inventarios_detector_job.py')


def _text():
    return TARGET.read_text(encoding='utf-8')


def test_retry_rehydrates_details_json_context():
    text = _text()
    required = [
        "detalles_raw = registro.get('DetallesJSON')",
        "'folio_inicial': detalles.get('folio_inicial')",
        "'fecha_inicial': detalles.get('fecha_inicial')",
        "'fecha_inventario': detalles.get('fecha_inventario')",
        "'metadata': detalles.get('metadata', {})",
    ]
    for token in required:
        assert token in text


def test_new_tracking_persists_retry_context():
    text = _text()
    required = [
        '"folio_inicial": inv.folio_inicial',
        '"fecha_inicial": inv.fecha_inicial',
        '"fecha_inventario": inv.fecha_inventario',
        '"metadata": inv.metadata',
    ]
    for token in required:
        assert token in text


def test_email_remains_fail_closed():
    text = _text()
    assert 'SCHEDULER_INVENTARIOS_EMAIL_ENABLED' in text
    assert '"false"' in text[text.find('SCHEDULER_INVENTARIOS_EMAIL_ENABLED'):text.find('SCHEDULER_INVENTARIOS_EMAIL_ENABLED') + 120]
